package com.ailab.system.report.provider;
import com.ailab.system.report.config.*; import com.ailab.system.report.model.*; import java.math.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public final class TaskStatProvider extends AbstractLabDataSourceProvider { public TaskStatProvider(){super(ReportConfigCatalog.TASK_STAT,new LinkedHashSet<String>(Arrays.asList("status","resultStatus","total")));} protected ReportSectionData loadValidated(ReportQueryCriteria c,ReportSectionConfig s){List<Map<String,Object>> r=copyRows(mapper().selectTaskStats(c)); Map<String,Object> x=new LinkedHashMap<String,Object>(); x.put("count",r.size()); x.put("total",total(r)); return section(c,s,r,x);} @Override protected void recomputeFilteredSummary(List<Map<String,Object>> rows,Map<String,Object>summary){summary.put("total",total(rows));} private BigDecimal total(List<Map<String,Object>> rows){BigDecimal total=BigDecimal.ZERO;for(Map<String,Object> row:rows)total=total.add(number(row.get("total")));return total;}}
